import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines an update record trigger with non-default runtime options.

Flow(
    {
        $id: Now.ID['flow_trigger_update_record'],
        name: 'Flow - Trigger Update Record',
        description: 'Flow used by tests to validate update record trigger configuration.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.updated,
        { $id: Now.ID['trigger_update_record'], annotation: 'Trigger on record update' },
        {
            table: 'incident',
            condition:
                'opened_atONLast week@javascript:gs.beginningOfLastWeek()@javascript:gs.endOfLastWeek()^priority=1^state=1',
            run_on_extended: 'false',
            run_flow_in: 'foreground',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'not_one_of',
            trigger_strategy: 'once',
        }
    ),
    () => {
        // Empty body; this test focuses on trigger configuration only
    }
)
